+  .tag.on { background: var(--action); color: var(--action-ink); border-color: transparent; }
+  .sw { display: flex; justify-content: space-between; align-items: center; padding: 11px 0; border-top: 1px solid var(--line); font-size: 14px; }
+  .sw:first-of-type { border-top: 0; }
