+  .sw i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--card); box-shadow: 0 1px 2px rgb(0 0 0 / .3); }
+  .sw i.on { background: var(--action); } .sw i.on::after { left: 16px; background: var(--action-ink); }
+  .week { display: grid; grid-template-columns: 64px repeat(5, 1fr); gap: 6px; font-size: 12.5px; }
+  .week > div { padding: 8px 8px; border-radius: 8px; background: color-mix(in oklab, var(--ink) 5%, var(--card)); min-height: 34px; }
+  .week > .h { background: none; color: var(--muted); padding: 4px 8px; }
+  .week > .c { background: color-mix(in oklab, var(--accent) 18%, var(--card)); }
+  .week > .n { background: none; color: var(--muted); padding-left: 0; }
+  .bubble { padding: 10px 12px; border-radius: 12px; background: color-mix(in oklab, var(--ink) 6%, var(--card)); max-width: 86%; }
+  .bubble.me { margin-left: auto; background: var(--action); color: var(--action-ink); }
+  .stack > * + * { margin-top: 8px; }
