+  .steps li { display: grid; gap: 10px; align-content: start; padding-top: 18px; border-top: 1px solid var(--line-strong); }
+  .nav .btn { height: 36px; }
+  .vh { min-height: 0; }
+  .center { text-align: center; justify-items: center; }
+  .stats4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 24px; }
