+    return w;
+  };
+  const choose = (cands, nbrs, used) => {
+    const ws = cands.map(g => weightOf(g, nbrs, used)), tot = ws.reduce((s, x) => s + x, 0);
+    let r = rand() * tot, i = 0;
+    while (i < ws.length - 1 && (r -= ws[i]) > 0) i++;
