+    let ok = true;
+    for (const i of [...at].sort((a, b) => a - b)) {
+      const used = pl.filter(Boolean);
+      const cands = pool.filter(g => fits(g, slots[i]) &&!used.some(u => u.id === g.id || (u.avoids || []).includes(g.id) || (g.avoids || []).includes(u.id)));
