+}
+
+export function readIndex() { return JSON.parse(fs.readFileSync(path.join(HERE, 'index.json'), 'utf8')); }
+
+/* ---------------------------------------------------------------- command line */
+// a path compared by its real location, so a symlinked install (install.sh) is the same file
