+/* fx-band: a divider band between two sections, its effect kept to the far side of the headline */
+.cx-band {
+  position: relative; isolation: isolate; overflow: hidden; display: flex; align-items: center;
+  min-height: 320px; padding: var(--s-7) var(--s-8); border-radius: var(--r-lg);
+  background: var(--cx-card); border: 1px solid var(--cx-line);
+}
+/* the effect lives in the right part and fades in from the copy's side; the script sets its left edge
