+/* fx-photo: the section's own photograph in natural colour, the copy in a solid card inset in its corner
+   (never a gradient scrim over the picture). .is-graded (data-cx-grade="duotone"): the picture graded into
+   the page tones. */
+.cx-photo__frame {
+  position: relative; isolation: isolate; overflow: hidden; display: flex; align-items: flex-end;
+  aspect-ratio: 16 / 8; min-height: 380px; border-radius: var(--r-lg); background: var(--cx-panel);
+}
+.cx-photo__frame > img {
+  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: 60% 62%; z-index: -2;
+  transition: transform 1.4s var(--cx-ease);
+}
+/* no scrim and no word straight on the picture: the copy stands in a solid card inset in the corner */
+@media (hover: hover) and (prefers-reduced-motion: no-preference) {
+  .cx-photo:not(.is-graded) .cx-photo__frame:hover > img { transform: scale(1.03); }
+}
+.cx-photo__copy { position: relative; display: grid; justify-items: start; gap: var(--s-3); max-width: 460px; margin: var(--s-6); padding: var(--s-6); border-radius: var(--r-md, var(--r-lg)); background: var(--bg); }
