+.cx-photo__title { font: 500 clamp(24px, 1.2vw + 16px, 32px)/1.15 var(--font-display); letter-spacing: -0.02em; margin: 0; color: var(--ink); text-wrap: balance; }
+.cx-photo__link {
+  display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 14px; margin-top: var(--s-2);
+  border-radius: var(--r-btn); background: var(--bg); color: var(--ink); font-size: var(--t-small); font-weight: 500;
+  border: 1px solid var(--cx-line-2);
+}
+.cx-photo__link::after { content: "\2192"; transition: transform var(--dur) var(--ease); }
+.cx-photo__link:hover::after { transform: translateX(3px); }
+@media (max-width: 639px) {
+  .cx-photo__frame { aspect-ratio: 4 / 5; min-height: 0; }
+  .cx-photo__copy { margin: var(--s-4); padding: var(--s-5); max-width: none; }
+  .cx-photo__frame > img { object-position: 62% 50%; }
+}

