+    pend();
+    if (destroyed || queued || kept || !visible || document.hidden || !stale() || tries > 3) return;
+    queued = true;
+    stillChain = stillChain.then(render, render).then(() => { queued = false; want(); });
+  };
+  const keep = ctrl => { kept = ctrl; ready(); pend(); };
