+    el,
+    still: true,
+    ready: readyP,
+    pause() {},
+    resume() {},
+    get info() { return kept ? kept.info : { still: true, webgl: 0, running: false, size: pic ? [pic.width, pic.height] : null }; },
+    destroy() {
+      destroyed = true;
+      pend();
