+      extras = [];
+    },
+  };
+}
+
+/* ------------------------------------------------------------------ fill */
+
+/**
+  fill(el, id, opts): the glyphs of el show the effect. Mark the parts with data-fill (text, an
+  icon drawn in currentColor, a .cx-glyph mask icon) or data-fill="box" (the element's whole box,
