+      return Pr;
+    },
+    ping(id, extra) { F.push({ e: -1, t0: Pr.t, dur: 0.01, dir: 1, hitT: 0, hit: id, ...(extra || {}) }); return Pr; },
+    wait(sec) { Pr.t += sec; return Pr; },
