+#define CURTAIN(A, B, FI) { float up_, hl_; float c_ = curtain(x, y, t, A, B, FI, up_, hl_); tint += mix(u_hem, u_top, clamp(up_ * 1.15 + FI * 0.12, 0.0, 1.0)) * c_; cover += c_; halo += hl_ * (1.0 - 0.2 * FI); }
